        ["MaintenanceWarning"] = T("Neustart und Werksreset greifen direkt in den Cube ein. Es wird nichts automatisch ausgeführt; erst die Vorschau und dann die ausdrückliche Bestätigung starten den Vorgang.", "Reboot and factory reset act directly on the cube. Nothing runs automatically; the preview and then explicit confirmation are required.", "Le redémarrage et la réinitialisation agissent directement sur le Cube. Rien n'est exécuté automatiquement ; un aperçu puis une confirmation explicite sont nécessaires.", "Riavvio e ripristino agiscono direttamente sul Cube. Nulla viene eseguito automaticamente: sono richiesti un'anteprima e poi una conferma esplicita.", "Opnieuw opstarten en fabrieksreset werken rechtstreeks op de Cube. Niets wordt automatisch uitgevoerd; eerst een voorbeeld en daarna expliciete bevestiging.", "Restart i reset fabryczny działają bezpośrednio na Cube. Nic nie jest wykonywane automatycznie; wymagane są podgląd i wyraźne potwierdzenie."),
        ["ConfirmReboot"] = T("Ich habe verstanden: Der Cube wird neu gestartet.", "I understand: the cube will be restarted.", "J'ai compris : le Cube va redémarrer.", "Ho capito: il Cube verrà riavviato.", "Ik begrijp het: de Cube wordt opnieuw opgestart.", "Rozumiem: Cube zostanie zrestartowany."),
        ["ConfirmFactoryReset"] = T("Ich habe verstanden: Alle Cube-Einstellungen werden unwiderruflich gelöscht.", "I understand: all cube settings will be irreversibly erased.", "J'ai compris : tous les paramètres du Cube seront irréversiblement effacés.", "Ho capito: tutte le impostazioni del Cube verranno cancellate irreversibilmente.", "Ik begrijp het: alle Cube-instellingen worden onomkeerbaar gewist.", "Rozumiem: wszystkie ustawienia Cube zostaną nieodwracalnie usunięte."),
        ["RebootCube"] = T("Cube neu starten", "Restart cube", "Redémarrer le Cube", "Riavvia Cube", "Cube opnieuw opstarten", "Zrestartuj Cube"),
        ["FactoryResetCube"] = T("Werksreset des Cubes", "Factory reset cube", "Réinitialisation du Cube", "Ripristino factory del Cube", "Fabrieksreset van Cube", "Reset fabryczny Cube"),
        ["PreviewReboot"] = T("Vorschau: Der Cube erhält einen Neustart-Befehl. Daten und Konfiguration bleiben erhalten.", "Preview: the cube receives a reboot command. Data and configuration are preserved.", "Aperçu : le Cube reçoit une commande de redémarrage. Les données et la configuration sont conservées.", "Anteprima: il Cube riceve un comando di riavvio. Dati e configurazione vengono conservati.", "Voorbeeld: de Cube ontvangt een herstartopdracht. Gegevens en configuratie blijven behouden.", "Podgląd: Cube otrzyma polecenie restartu. Dane i konfiguracja zostaną zachowane."),
        ["PreviewFactoryReset"] = T("Vorschau: Der Cube erhält einen Werksreset. Alle Einstellungen, Räume und Gerätezuordnungen im Cube gehen unwiderruflich verloren. Der lokale Cache bleibt erhalten und wird beim nächsten Lesen überschrieben.", "Preview: the cube receives a factory reset. All settings, rooms and device assignments in the cube may be lost. The local cache remains and is overwritten on the next read.", "Aperçu : le Cube reçoit une réinitialisation d'usine. Tous les paramètres, pièces et affectations d'appareils dans le Cube peuvent être perdus. Le cache local reste et sera écrasé lors de la prochaine lecture.", "Anteprima: il Cube riceve un ripristino di fabbrica. Tutte le impostazioni, stanze e assegnazioni dei dispositivi nel Cube possono andare perse. La cache locale resta e viene sovrascritta alla prossima lettura.", "Voorbeeld: de Cube ontvangt een fabrieksreset. Alle instellingen, kamers en apparaatkoppelingen in de Cube kunnen verloren gaan. De lokale cache blijft en wordt bij de volgende lezing overschreven.", "Podgląd: Cube otrzyma reset fabryczny. Wszystkie ustawienia, pokoje i przypisania urządzeń w Cube mogą zostać utracone. Lokalna pamięć podręczna pozostaje i zostanie nadpisana przy następnym odczycie."),
        ["ErrReboot"] = T("Neustart fehlgeschlagen", "Reboot failed", "Échec du redémarrage", "Riavvio non riuscito", "Opnieuw opstarten mislukt", "Restart nie udał się"),
        ["OkReboot"] = T("Neustart-Befehl gesendet.", "Reboot command sent.", "Commande de redémarrage envoyée.", "Comando di riavvio inviato.", "Herstartopdracht verzonden.", "Polecenie restartu wysłane."),
        ["ErrFactoryReset"] = T("Werksreset fehlgeschlagen", "Factory reset failed", "Échec de la réinitialisation", "Ripristino di fabbrica non riuscito", "Fabrieksreset mislukt", "Reset fabryczny nie udał się"),
        ["OkFactoryReset"] = T("Werksreset-Befehl gesendet.", "Factory reset command sent.", "Commande de réinitialisation envoyée.", "Comando di ripristino inviato.", "Opdracht voor fabrieksreset verzonden.", "Polecenie resetu fabrycznego wysłane."),
        ["WakeUp"] = T("Raum aufwecken", "Wake room", "Réveiller la pièce", "Risveglia stanza", "Ruimte wekken", "Obudź pomieszczenie"),
        ["ConfirmWakeUp"] = T("Ich habe verstanden: Es wird ein Funk-Wake-up gesendet.", "I understand: a radio wake-up will be sent.", "J'ai compris : un réveil radio sera envoyé.", "Ho capito: verrà inviato un risveglio radio.", "Ik begrijp het: er wordt een radio-wek-opdracht verzonden.", "Rozumiem: zostanie wysłane radiowe wybudzenie."),
        ["WakeUpDuration"] = T("Dauer (Minuten)", "Duration (minutes)", "Durée (minutes)", "Durata (minuti)", "Duur (minuten)", "Czas trwania (minuty)"),
        ["WakeUpHint"] = T("Wake-up ist ein schreibender Funkbefehl. Die Quittung bestätigt nur die Annahme durch den Cube, nicht die Wirkung an den Geräten.", "Wake-up is a radio write command. The acknowledgement only confirms acceptance by the cube, not the effect on devices.", "Le réveil est une commande radio en écriture. L'accusé de réception confirme seulement l'acceptation par le Cube, pas l'effet sur les appareils.", "Il risveglio è un comando radio in scrittura. La conferma attesta solo l'accettazione da parte del Cube, non l'effetto sui dispositivi.", "Wake-up is een schrijvende radio-opdracht. De bevestiging bevestigt alleen aanvaarding door de Cube, niet het effect op apparaten.", "Wybudzenie to radiowe polecenie zapisu. Potwierdzenie oznacza tylko przyjęcie przez Cube, nie wpływ na urządzenia."),
        ["PreviewWakeUp"] = T("Vorschau: Wake-up an Raum {0} für {1} Minuten senden?", "Preview: send wake-up to room {0} for {1} minutes?", "Aperçu : envoyer le réveil à la pièce {0} pendant {1} minutes ?", "Anteprima: inviare il risveglio alla stanza {0} per {1} minuti?", "Voorbeeld: wake-up naar ruimte {0} sturen voor {1} minuten?", "Podgląd: wysłać wybudzenie do pomieszczenia {0} na {1} minut?"),
        ["ErrWakeUp"] = T("Wake-up fehlgeschlagen", "Wake-up failed", "Échec du réveil", "Risveglio non riuscito", "Wake-up mislukt", "Wybudzenie nie udało się"),
        ["OkWakeUp"] = T("Wake-up gesendet.", "Wake-up sent.", "Réveil envoyé.", "Risveglio inviato.", "Wake-up verzonden.", "Wybudzenie wysłane."),
        ["NetDhcpNote"] = T("Bei DHCP ist die konfigurierte IP nicht die aktive Adresse. Beide Werte werden getrennt angezeigt; das Lesen erfolgt immer über den verbundenen Endpoint.", "With DHCP the configured IP is not the active address. Both values are shown separately; reading always uses the connected endpoint.", "Avec DHCP, l'IP configurée n'est pas l'adresse active. Les deux valeurs sont affichées séparément ; la lecture utilise toujours le point de terminaison connecté.", "Con DHCP l'IP configurata non è l'indirizzo attivo. I due valori sono mostrati separatamente; la lettura usa sempre l'endpoint connesso.", "Bij DHCP is het geconfigureerde IP niet het actieve adres. Beide waarden worden apart getoond; lezen gebruikt altijd het verbonden endpoint.", "Przy DHCP skonfigurowane IP nie jest adresem aktywnym. Obie wartości są pokazywane osobno; odczyt zawsze używa połączonego endpointu."),
