        ["ErrNoZone"] = T("Keine Zeitzone ausgewählt.", "No time zone selected.", "Aucun fuseau horaire sélectionné.", "Nessun fuso orario selezionato.", "Geen tijdzone geselecteerd.", "Nie wybrano strefy czasowej."),
