        ["LogRetention"] = T("Logdateien aufbewahren (Tage)", "Keep log files (days)", "Conserver les fichiers journaux (jours)", "Conserva i file di log (giorni)", "Logbestanden bewaren (dagen)", "Przechowuj pliki dziennika (dni)"),
        ["LogRetentionHint"] = T("Ältere Logdateien werden beim Start gelöscht.", "Older log files are deleted at startup.", "Les anciens fichiers journaux sont supprimés au démarrage.", "I file di log più vecchi vengono eliminati all'avvio.", "Oudere logbestanden worden bij het opstarten verwijderd.", "Starsze pliki dziennika są usuwane przy uruchomieniu."),
        ["AuditRetention"] = T("Audit aufbewahren (Tage)", "Keep audit history (days)", "Conserver l'historique d'audit (jours)", "Conservare la cronologia audit (giorni)", "Auditgeschiedenis bewaren (dagen)", "Przechowywanie audytu (dni)"),
        ["AuditRetentionHint"] = T("Ältere Audit-Einträge werden beim Start gelöscht.", "Older audit entries are deleted at startup.", "Les anciennes entrées d'audit sont supprimées au démarrage.", "Le voci di audit più vecchie vengono eliminate all'avvio.", "Oudere audititems worden bij het opstarten verwijderd.", "Starsze wpisy audytu są usuwane przy uruchomieniu."),
        ["BundleTemperatures"] = T("Temperaturänderungen bündeln", "Bundle temperature changes", "Regrouper les changements de température", "Raggruppa le modifiche di temperatura", "Temperatuurwijzigingen bundelen", "Grupuj zmiany temperatury"),
        ["BundleHint"] = T("Sammelt Temperaturen 3 Sekunden und sendet pro Raum nur den letzten Wert. Das spart Funkverkehr.", "Collects temperatures for 3 seconds and sends only the last value per room. This saves radio traffic.", "Collecte les températures pendant 3 secondes et n'envoie que la dernière valeur par pièce. Cela économise le trafic radio.", "Raccoglie le temperature per 3 secondi e invia solo l'ultimo valore per stanza. Risparmia traffico radio.", "Verzamelt temperaturen gedurende 3 seconden en verzendt per ruimte alleen de laatste waarde. Dat spaart radioverkeer.", "Zbiera temperatury przez 3 sekundy i wysyła tylko ostatnią wartość dla pomieszczenia. Oszczędza to ruch radiowy."),
        ["CloseToTray"] = T("Schließen versteckt das Fenster im Systemtray", "Closing hides the window in the system tray", "La fermeture masque la fenêtre dans la zone de notification", "La chiusura nasconde la finestra nell'area di notifica", "Sluiten verbergt het venster in het systeemvak", "Zamknięcie ukrywa okno w zasobniku systemowym"),
        ["CloseToTrayHint"] = T("Nur aktivieren, wenn Ihr Desktop ein Tray-Symbol anzeigt; über das Symbol beenden Sie die App.", "Only enable if your desktop shows a tray icon; you quit the app from that icon.", "À activer seulement si votre bureau affiche une icône de notification ; on quitte l'application depuis cette icône.", "Attiva solo se il desktop mostra un'icona nell'area di notifica; l'app si chiude da quell'icona.", "Alleen inschakelen als uw bureaublad een systeemvakpictogram toont; via dat pictogram sluit u de app af.", "Włącz tylko, jeśli pulpit pokazuje ikonę w zasobniku; z niej zamykasz aplikację."),
        ["TrayShow"] = T("Fenster anzeigen", "Show window", "Afficher la fenêtre", "Mostra finestra", "Venster tonen", "Pokaż okno"),
        ["TrayExit"] = T("Beenden", "Exit", "Quitter", "Esci", "Afsluiten", "Zakończ"),
        ["AlreadyRunningTitle"] = T("MAX! Cube läuft bereits", "MAX! Cube is already running", "MAX! Cube est déjà en cours d'exécution", "MAX! Cube è già in esecuzione", "MAX! Cube draait al", "MAX! Cube jest już uruchomiony"),
        ["AlreadyRunning"] = T("Eine andere Instanz der App läuft bereits. Der Cube erlaubt nur eine Verbindung; bitte nutzen Sie die laufende Instanz.", "Another instance of the app is already running. The cube allows only one connection; please use the running instance.", "Une autre instance de l'application est déjà en cours. Le Cube n'autorise qu'une connexion ; utilisez l'instance existante.", "Un'altra istanza dell'app è già in esecuzione. Il Cube consente una sola connessione; usa l'istanza in esecuzione.", "Er draait al een andere instantie van de app. De Cube staat maar één verbinding toe; gebruik de lopende instantie.", "Inna instancja aplikacji jest już uruchomiona. Cube dopuszcza tylko jedno połączenie; użyj działającej instancji."),
        ["OkTemperatureQueued"] = T("Temperatur vorgemerkt – wird nach {0} s gebündelt gesendet.", "Temperature queued – sent bundled after {0} s.", "Température en attente – envoyée groupée après {0} s.", "Temperatura in coda – inviata raggruppata dopo {0} s.", "Temperatuur in wachtrij – na {0} s gebundeld verzonden.", "Temperatura zakolejkowana – wysłana zbiorczo po {0} s."),
        ["ExcludedFeatures"] = T("Bewusst nicht enthalten: Cloud-/Fernzugriff, Produktkonto, Proxy, Update-Download und das Schreiben der Cube-Firmware (Cloud abgeschaltet seit 01.07.2023, Risiko eines defekten Geräts).", "Deliberately not included: cloud/remote access, product account, proxy, update download and writing cube firmware (cloud shut down since 2023-07-01, risk of bricking the device).", "Volontairement absents : accès cloud/distant, compte produit, proxy, téléchargement de mises à jour et écriture du firmware du Cube (cloud arrêté depuis le 01/07/2023, risque de rendre l'appareil inutilisable).", "Volutamente non inclusi: accesso cloud/remoto, account prodotto, proxy, download aggiornamenti e scrittura del firmware del Cube (cloud disattivato dal 01/07/2023, rischio di danneggiare il dispositivo).", "Bewust niet opgenomen: cloud-/externe toegang, productaccount, proxy, updatedownload en het schrijven van Cube-firmware (cloud uitgeschakeld sinds 01-07-2023, risico op een defect apparaat).", "Celowo pominięte: dostęp chmurowy/zdalny, konto produktu, proxy, pobieranie aktualizacji i zapis oprogramowania Cube (chmura wyłączona od 01.07.2023, ryzyko uszkodzenia urządzenia)."),

