        ["ErrConnectRefused"] = T("Cube unter {0}:{1} nicht erreichbar – IP/Port prüfen und andere Clients trennen.", "Cube at {0}:{1} unreachable – check IP/port and disconnect other clients.", "Cube à {0}:{1} inaccessible – vérifiez l'IP/le port et déconnectez les autres clients.", "Cube all'indirizzo {0}:{1} non raggiungibile – controlla IP/porta e scollega altri client.", "Cube op {0}:{1} onbereikbaar – controleer IP/poort en verbreek andere clients.", "Cube pod adresem {0}:{1} nieosiągalny – sprawdź IP/port i odłącz innych klientów."),
        ["ErrConnectHello"] = T("Cube hat keinen gültigen Handshake gesendet – Cube neu starten und anderen Client trennen.", "Cube did not send a valid handshake – restart the cube and disconnect other clients.", "Le Cube n'a pas envoyé de poignée de main valide – redémarrez le Cube et déconnectez les autres clients.", "Il Cube non ha inviato un handshake valido – riavvia il Cube e scollega altri client.", "Cube heeft geen geldige handshake verzonden – Cube opnieuw starten en andere clients verbreken.", "Cube nie wysłał poprawnego uzgadniania – zrestartuj Cube i odłącz innych klientów."),
