        ["ErrConnectFirmware"] = T("Cube-Firmware wird nicht unterstützt – nur Firmware 273–275 wird bedient.", "Cube firmware is not supported – only firmware 273–275 is handled.", "Le firmware du Cube n'est pas pris en charge – seuls les firmware 273–275 sont pris en charge.", "Firmware del Cube non supportato – vengono gestiti solo i firmware 273–275.", "Cube-firmware wordt niet ondersteund – alleen firmware 273–275 wordt bediend.", "Oprogramowanie Cube nie jest obsługiwane – obsługiwane są tylko wersje 273–275."),
        ["ErrConnectAlready"] = T("Es besteht bereits eine Verbindung zum Cube – zuerst trennen.", "Already connected to the cube – disconnect first.", "Déjà connecté au Cube – déconnectez d'abord.", "Già connessi al Cube – scollegare prima.", "Er is al verbinding met de Cube – verbreek eerst.", "Połączenie z Cubem już istnieje – najpierw odłącz."),
